// Lo que pidió Sofía y las filas de la hoja (columnas: tratamiento, precio,
// duracion, notas). Se compara sin acentos ni mayúsculas.
const llamada = $('Webhook del CRM').first().json.body || {};
const sinAcentos = (t) => String(t || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
const pedido = sinAcentos(llamada.args?.tratamiento);
const filas = $input.all().map((i) => i.json).filter((f) => f.tratamiento);

if (!pedido) {
  return [{ json: { resultado: 'No me dijeron qué tratamiento buscar.' } }];
}

const fila =
  filas.find((f) => sinAcentos(f.tratamiento) === pedido) ||
  filas.find((f) => sinAcentos(f.tratamiento).includes(pedido) || pedido.includes(sinAcentos(f.tratamiento)));

if (!fila) {
  const hay = filas.map((f) => f.tratamiento).join(', ');
  return [{ json: { resultado: `«${llamada.args.tratamiento}» no está en la lista de precios. Los que hay: ${hay}.` } }];
}

let texto = `${fila.tratamiento}: ${fila.precio}`;
if (fila.duracion) texto += `, dura ${fila.duracion}`;
texto += '.';
if (fila.notas) texto += ` ${fila.notas}.`;
return [{ json: { resultado: texto } }];
